function printFixActions(actions, dryRun) {
    if (actions.length === 0) {
        console.log(`${chalk.green("✓")} Nothing to repair\n`);
        return;
    }
    for (const action of actions) {
        const label = action.status === "planned"
            ? `${chalk.cyan("would run")}`
            : action.status === "applied"
                ? chalk.green("ran")
                : action.status === "failed"
                    ? chalk.red("failed")
                    : chalk.gray("skipped");
        const detail = action.status === "planned" ? "" : ` (${action.reason})`;
        console.log(`${label}: ${action.command}${detail}`);
    }
    if (dryRun)
        console.log(chalk.gray("\nDry run: nothing was changed."));
    console.log("");
}
function printDoctorResults(list) {
    for (const result of orderDoctorResults(list)) {
        if (!result.didPass && !result.isSkipped && !result.isWarning) {
            console.log(`${chalk.red("✗")} ${result.message}`);
            if (result.fix)
                console.log(`${chalk.blue("ℹ")} Fix: ${result.fix}`);
        }
        else if (result.isWarning) {
            console.log(`${chalk.yellow("⚠")} ${chalk.yellow(result.message)}`);
            if (result.fix)
                console.log(`${chalk.blue("ℹ")} Fix: ${result.fix}`);
        }
        else if (result.isSkipped) {
            console.log(`${chalk.gray("○")} ${chalk.gray(result.message)}`);
            if (result.fix)
                console.log(`${chalk.blue("ℹ")} ${result.fix}`);
        }
        else {
            console.log(`${chalk.green("✓")} ${result.message}`);
        }
    }
}
